SELECT/*selectRevision*/							
		NVL(MAX(AGENT_REVISION)+1,0) AS AGENT_REVISION
		, NVL(MAX(AGENT_REVISION)+1,0) -1 AS PRE_AGENT_REVISION
  FROM KEPQTDT					
 WHERE BUYER=#{st_buyer_code} 					
	AND QUOTATION_NO=#{st_quotation_no}		
	AND QUOTATION_SEQ=#{st_quotation_seq}				
	AND REVISION=#{st_revision}     			
	AND STATUS IN ('C','R','O')

