	UPDATE KEPQTDT	/*updateChkFlag*/				
	   SET STATUS='O'  
    WHERE BUYER=#{st_buyer_code}   
      AND QUOTATION_NO=#{st_quotation_no}   
      AND QUOTATION_SEQ=#{st_quotation_seq}     
      AND REVISION=#{st_revision}       
      AND STATUS IN ('C','R')


	UPDATE KEPRQDT   /*updateRqdt*/             
      SET ATOB_SEND_FLAG='N',    
          ATOS_REMARK=#{st_atos_remark},
          ATOS_REMARK2=ATOS_REMARK2||#{AGENT_REVISION}||'차: '||#{st_atos_remark}||',',
          KEP_USER_ID=#{USER_ID},
          SELLER_IMAGE_KEY = #{st_seller_image_key}
    WHERE BUYER=#{st_buyer_code}     
      AND QUOTATION_NO=#{st_quotation_no} 
      AND QUOTATION_SEQ=#{st_quotation_seq} 
      AND REVISION=#{st_revision}
      AND STATUS <> 'D'


	UPDATE KEPRQDT   /*updateRqdt2*/             
      SET ATOB_SEND_FLAG='N',    
          ATOS_REMARK=#{st_atos_remark},
          ATOS_REMARK2=ATOS_REMARK2||#{AGENT_REVISION2}||'차: '||#{st_atos_remark}||',',
          KEP_USER_ID=#{USER_ID},
          MSDS_NO = '',
          MSDS_USER_ID = ''
    WHERE BUYER=#{st_buyer_code}     
      AND QUOTATION_NO=#{st_quotation_no} 
      AND QUOTATION_SEQ=#{st_quotation_seq} 
      AND REVISION=#{st_revision}
      AND STATUS <> 'D'

