/*selectQtdtAgentInfo*/
	SELECT
	 TO_CHAR(QTDT.STOA_LIST_PRICE) AS STOA_LIST_PRICE
	 ,TO_CHAR(QTDT.LEAD_TIME) AS LEAD_TIME
	 ,QTDT.SEL_USER_ID
	 ,QTDT.SEL_USER_NAME
	 ,TO_CHAR(QTDT.SEL_USER_TEL) AS SEL_USER_TEL
	FROM KEPQTDT QTDT
	WHERE QTDT.BUYER = #{st_buyer_code}
	AND QTDT.QUOTATION_NO = #{st_quotation_no}
	AND QTDT.QUOTATION_SEQ = #{st_quotation_seq}
	AND QTDT.AGENT_REVISION = #{PRE_AGENT_REVISION}
	AND QTDT.AGENT = #{AGENT}
	AND ROWNUM =1
